pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address alice = address(0x1);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(alice);
        c.withdrawAll();
        bool ok;
        vm.prank(alice);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
